-- ----------------------------
-- Table structure for annual_configuration
-- ----------------------------
DROP TABLE IF EXISTS `annual_configuration`;
CREATE TABLE `annual_configuration`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `config_year` int(4) NOT NULL COMMENT '配置年份',
  `ghg_intensity_target` decimal(20, 10) NULL DEFAULT NULL COMMENT 'GHG强度目标值 (gCO2eq/MJ)',
  `cii_reduction_rate` decimal(10, 4) NULL DEFAULT NULL COMMENT '年度减排比例 (%)',
  `fuel_eu_penalty` decimal(10, 2) NULL DEFAULT NULL COMMENT 'FuelEU超额每吨罚金（欧元/吨CO2）',
  `eua_price` decimal(10, 2) NULL DEFAULT NULL COMMENT 'EUA价格（欧元/吨CO2）',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0:停用 1:启用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_config_year`(`config_year`) USING BTREE,
  INDEX `idx_config_year`(`config_year`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '年度配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of annual_configuration
-- ----------------------------

-- ----------------------------
-- Table structure for cii_config
-- ----------------------------
DROP TABLE IF EXISTS `cii_config`;
CREATE TABLE `cii_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ship_type_id` bigint(20) NOT NULL COMMENT '船舶类型ID',
  `applicable_standard` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '适用标准（GT:总吨位 DWT:载重吨位）',
  `range_min` decimal(15, 2) NOT NULL COMMENT '匹配区间最小值',
  `range_max` decimal(15, 2) NULL DEFAULT NULL COMMENT '匹配区间最大值',
  `constant_a` decimal(65, 6) NOT NULL COMMENT '常量a',
  `constant_c` decimal(15, 6) NOT NULL COMMENT '常量c',
  `d1` decimal(10, 4) NOT NULL COMMENT 'D1阈值（A/B级分界线）',
  `d2` decimal(10, 4) NOT NULL COMMENT 'D2阈值（B/C级分界线）',
  `d3` decimal(10, 4) NOT NULL COMMENT 'D3阈值（C/D级分界线）',
  `d4` decimal(10, 4) NOT NULL COMMENT 'D4阈值（D/E级分界线）',
  `constant_capacity` decimal(15, 6) NOT NULL COMMENT '常量Capacity',
  `use_max` tinyint(1) NULL DEFAULT 0,
  `status` int(1) NOT NULL DEFAULT 1 COMMENT '状态（0:停用 1:启用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ship_type_id`(`ship_type_id`) USING BTREE,
  INDEX `idx_applicable_standard`(`applicable_standard`) USING BTREE,
  INDEX `idx_range`(`range_min`, `range_max`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CII计算常量表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of cii_config
-- ----------------------------

-- ----------------------------
-- Table structure for cii_evaluation_detail
-- ----------------------------
DROP TABLE IF EXISTS `cii_evaluation_detail`;
CREATE TABLE `cii_evaluation_detail`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `year` int(11) NOT NULL COMMENT '评估年份',
  `start_time` bigint(20) NOT NULL COMMENT '开始时间',
  `end_time` bigint(20) NOT NULL COMMENT '结束时间',
  `emission_value` decimal(19, 4) NOT NULL COMMENT '排放值（CII Attained）',
  `benchmark_value` decimal(19, 4) NOT NULL COMMENT '基准值（CII Reference）',
  `cii_required` decimal(19, 4) NULL DEFAULT NULL,
  `score` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评分（CII Rating）',
  `rating` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评级（A/B/C/D/E）',
  `status` int(11) NULL DEFAULT 1 COMMENT '状态（0:无效 1:有效）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_year`(`year`) USING BTREE,
  INDEX `idx_rating`(`rating`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'CII评估明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of cii_evaluation_detail
-- ----------------------------

