-- ----------------------------
-- Table structure for eu_ets_summary
-- ----------------------------
DROP TABLE IF EXISTS `eu_ets_summary`;
CREATE TABLE `eu_ets_summary`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `year` int(4) NOT NULL COMMENT '年份',
  `total_emissions` decimal(15, 4) NULL DEFAULT NULL COMMENT '累计排放量（吨）',
  `total_penalty` decimal(15, 2) NULL DEFAULT NULL COMMENT '累计罚金',
  `voyage_count` int(11) NULL DEFAULT 0 COMMENT '航次数量',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态 0=正常 1=删除',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ship_year`(`ship_id`, `year`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_year`(`year`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'EU ETS汇总数据表' ROW_FORMAT = Dynamic;

