-- ----------------------------
-- Table structure for fuel_eu_calculation_result
-- ----------------------------
DROP TABLE IF EXISTS `fuel_eu_calculation_result`;
CREATE TABLE `fuel_eu_calculation_result`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `assessment_year` int(4) NOT NULL COMMENT '评估年份',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `well_to_tank_ship` decimal(15, 6) NOT NULL COMMENT 'Well to tank ship值 (gCO2eq/MJ)',
  `tank_to_wake_ship` decimal(15, 6) NOT NULL COMMENT 'Tank to wake ship值 (gCO2eq/MJ)',
  `co2eq_emitted_ttw` decimal(25, 6) NULL DEFAULT NULL COMMENT 'CO2eq TtW值 (gCO2eq/MJ)',
  `co2eq_emitted_wtt` decimal(25, 6) NULL DEFAULT NULL COMMENT 'CO2eq TtW slip值 (gCO2eq/MJ)',
  `ghg_actual_value` decimal(20, 10) NULL DEFAULT NULL COMMENT 'GHG实际值，计算公式：RWD-wind * (Well to tank ship + Tank to wake ship)',
  `calculation_status` tinyint(1) NULL DEFAULT 0 COMMENT '计算状态（0:草稿 1:已计算 2:已审核）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `energy_used_on_board` decimal(15, 6) NULL DEFAULT NULL,
  `shore_power_input` decimal(15, 6) NULL DEFAULT NULL,
  `base_penalty_amount` decimal(15, 6) NULL DEFAULT NULL COMMENT '基础罚金金额 (EUR)',
  `excess_penalty_amount` decimal(15, 6) NULL DEFAULT NULL COMMENT '超额罚金金额 (EUR)',
  `total_penalty_amount` decimal(15, 6) NULL DEFAULT NULL COMMENT '总罚金金额 (EUR)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_assessment_year`(`assessment_year`) USING BTREE,
  INDEX `idx_calculation_status`(`calculation_status`) USING BTREE,
  INDEX `idx_create_time`(`create_time`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'FuelEU计算结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fuel_eu_calculation_result
-- ----------------------------

-- ----------------------------
-- Table structure for fuel_type
-- ----------------------------
DROP TABLE IF EXISTS `fuel_type`;
CREATE TABLE `fuel_type`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID（1=公用数据，其他=租户私有数据）',
  `fuel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '燃料名称',
  `fuel_class` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '燃料类别',
  `lcv` decimal(10, 6) NULL DEFAULT NULL COMMENT '低热值 (MJ/kg)',
  `co2eq_wtt` decimal(10, 6) NULL DEFAULT NULL COMMENT '油井到油轮CO2当量排放 (gCO2eq/MJ)',
  `co2eq_ttw` decimal(10, 6) NULL DEFAULT NULL COMMENT '油轮到车轮CO2当量排放 (gCO2eq/MJ)',
  `co2eq_wtw` decimal(10, 6) NULL DEFAULT NULL COMMENT '全生命周期CO2当量排放 (gCO2eq/MJ)',
  `cf_co2` decimal(10, 6) NULL DEFAULT NULL COMMENT 'CO2成本因子',
  `cf_ch4` decimal(10, 6) NULL DEFAULT NULL COMMENT 'CH4成本因子',
  `cf_n2o` decimal(10, 6) NULL DEFAULT NULL COMMENT 'N2O成本因子',
  `cslip` decimal(10, 6) NULL DEFAULT NULL COMMENT '碳滑系数',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0:停用 1:启用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `gwp_co2` decimal(10, 4) NULL DEFAULT 1.0000 COMMENT 'CO2全球变暖潜能值',
  `gwp_ch4` decimal(10, 4) NULL DEFAULT 28.0000 COMMENT 'CH4全球变暖潜能值',
  `gwp_n2o` decimal(10, 4) NULL DEFAULT 265.0000 COMMENT 'N2O全球变暖潜能值',
  `csf_co2` decimal(10, 4) NULL DEFAULT 0.0000,
  `csf_ch4` decimal(10, 4) NULL DEFAULT 1.0000 COMMENT 'CH4气候敏感因子',
  `csf_n2o` decimal(10, 4) NULL DEFAULT 0.0000,
  `year` int(11) NULL DEFAULT NULL COMMENT '年份',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '燃料价格(元/吨)',
  `cf_co2eq` decimal(10, 4) NULL DEFAULT NULL COMMENT 'ETS co2转换系数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  INDEX `idx_tenant_fuel_year`(`tenant_id`, `fuel`, `year`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '燃料类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fuel_type
-- ----------------------------

