  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `imo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'IMO号',
  `start_port` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '起始港口',
  `end_port` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终点港口',
  `departure_time` datetime NULL DEFAULT NULL COMMENT '离港时间',
  `arrival_time` datetime NULL DEFAULT NULL COMMENT '到港时间',
  `route_distance` double NULL DEFAULT NULL COMMENT '航线距离（海里）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_imo`(`imo`) USING BTREE,
  INDEX `idx_departure_time`(`departure_time`) USING BTREE,
  INDEX `idx_arrival_time`(`arrival_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 629 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '全局航次表（不含租户隔离）' ROW_FORMAT = Dynamic;

