-- ----------------------------
-- Table structure for monthly_fuel_eu_calculation_result
-- ----------------------------
DROP TABLE IF EXISTS `monthly_fuel_eu_calculation_result`;
CREATE TABLE `monthly_fuel_eu_calculation_result`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `assessment_year` int(11) NOT NULL COMMENT '评估年份',
  `assessment_month` int(11) NOT NULL COMMENT '评估月份 (1-12)',
  `ghg_actual_value` decimal(20, 10) NULL DEFAULT NULL COMMENT 'GHG实际值 (gCO2eq/MJ)',
  `calculation_status` tinyint(1) NULL DEFAULT 0 COMMENT '计算状态（0:草稿 1:已计算 2:已审核）',
  `base_penalty_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '基础罚金金额 (EUR)',
  `excess_penalty_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '超额罚金金额 (EUR)',
  `total_penalty_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '总罚金金额 (EUR)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ship_year_month`(`ship_id`, `assessment_year`, `assessment_month`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_assessment_year`(`assessment_year`) USING BTREE,
  INDEX `idx_assessment_month`(`assessment_month`) USING BTREE,
  INDEX `idx_calculation_status`(`calculation_status`) USING BTREE,
  INDEX `idx_total_penalty_amount`(`total_penalty_amount`) USING BTREE,
  INDEX `idx_ghg_actual_value`(`ghg_actual_value`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '月度FuelEU计算结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of monthly_fuel_eu_calculation_result
-- ----------------------------

-- ----------------------------
-- Table structure for penalty_multiplier
-- ----------------------------
DROP TABLE IF EXISTS `penalty_multiplier`;
CREATE TABLE `penalty_multiplier`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `assessment_year` int(4) NOT NULL COMMENT '评估年份',
  `is_exceeded` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否超排（0:未超排 1:超排）',
  `penalty_factor` decimal(10, 2) NULL DEFAULT 1.00 COMMENT '超排系数（惩罚倍数）',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0:停用 1:启用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ship_year`(`ship_id`, `assessment_year`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_assessment_year`(`assessment_year`) USING BTREE,
  INDEX `idx_is_exceeded`(`is_exceeded`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  INDEX `idx_tenant_ship_year`(`tenant_id`, `ship_id`, `assessment_year`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '船舶惩罚系数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of penalty_multiplier
-- ----------------------------

