  `stay_in_port` decimal(10, 2) NULL DEFAULT NULL COMMENT '在港停留时间（小时）',
  `stay_in_terminal` decimal(10, 2) NULL DEFAULT NULL COMMENT '在码头停留时间（小时）',
  `raw_ata` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始到达时间字符串',
  `raw_atb` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始靠泊时间字符串',
  `raw_atd` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始离港时间字符串',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_mmsi`(`mmsi`) USING BTREE,
  INDEX `idx_ship_name`(`ship_name`) USING BTREE,
  INDEX `idx_port_code`(`port_code`) USING BTREE,
  INDEX `idx_ata`(`ata`) USING BTREE,
  INDEX `idx_mmsi_ata`(`mmsi`, `ata`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28842 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '船舶挂靠港口信息表' ROW_FORMAT = Dynamic;

