  `report_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告名',
  `ship_id` bigint(20) NULL DEFAULT NULL COMMENT '船舶ID',
