-- ----------------------------
-- Table structure for ship_charter_info
-- ----------------------------
DROP TABLE IF EXISTS `ship_charter_info`;
CREATE TABLE `ship_charter_info`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同编号',
  `charterer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '承租人名称',
  `lease_start_date` datetime NOT NULL COMMENT '租赁开始日期',
  `lease_end_date` datetime NOT NULL COMMENT '租赁结束日期',
  `lease_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '租赁方式,dict_type:carbon_less_type',
  `contract_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '租期合同路径',
  `main_fuel_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主燃料类型',
  `auxiliary_fuel_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '辅燃料类型',
  `main_fuel_consumption` decimal(10, 2) NULL DEFAULT NULL COMMENT '主燃料总消耗量（吨）',
  `auxiliary_fuel_consumption` decimal(10, 2) NULL DEFAULT NULL COMMENT '辅燃料总消耗量（吨）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `shore_electricity` decimal(10, 2) NULL DEFAULT NULL COMMENT '岸电输入总量',
  `bdn_path` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '油料单路径',
  `is_auto_generated` tinyint(1) NULL DEFAULT NULL COMMENT '是否自动生成：0-手动创建，1-自动补全',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_contract_no`(`contract_no`) USING BTREE,
  INDEX `idx_ship_year_auto`(`ship_id`, `lease_start_date`, `is_auto_generated`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  CONSTRAINT `fk_charter_ship` FOREIGN KEY (`ship_id`) REFERENCES `ship_info` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '船舶租期管理表' ROW_FORMAT = Dynamic;

