-- Records of ship_charter_info
-- ----------------------------

-- ----------------------------
-- Table structure for ship_info
-- ----------------------------
DROP TABLE IF EXISTS `ship_info`;
CREATE TABLE `ship_info`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '船舶名称',
  `ship_type_id` bigint(20) NOT NULL COMMENT '船舶类型ID',
  `imo_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'IMO编号',
  `gross_tonnage` decimal(15, 2) NOT NULL COMMENT '总吨位(GT)',
  `dead_weight` decimal(15, 2) NOT NULL COMMENT '载重吨(DWT)',
  `constant_a` decimal(65, 6) NULL DEFAULT NULL COMMENT 'CII计算常量a',
  `constant_capacity` decimal(15, 6) NULL DEFAULT NULL COMMENT 'CII计算常量Capacity',
  `constant_c` decimal(15, 6) NULL DEFAULT NULL COMMENT 'CII计算常量c',
  `status` int(1) NOT NULL DEFAULT 1 COMMENT '状态（0:停用 1:启用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `cii_measure_standard` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CII计量标准（GT:总吨位 DWT:载重吨位）',
  `wind_assisted_propulsion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风力辅助推进,dict_type:wind_assisted_propulsion',
  `main_engine_power` decimal(15, 6) NULL DEFAULT NULL COMMENT '船舶主机功率(kW)',
  `auxiliary_engine_power` decimal(15, 6) NULL DEFAULT NULL COMMENT '船舶辅机功率(kW)',
  `is_wind_power_applicable` int(1) NULL DEFAULT NULL COMMENT '是否适用风力风电',
  `wind_equipment_installation_time` datetime NULL DEFAULT NULL COMMENT '风力设备安装时间',
  `cii_applicable` tinyint(1) NULL DEFAULT 0 COMMENT '是否适用CII（0:不适用 1:适用）',
  `flag_state` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '船旗国',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ship_name`(`ship_name`) USING BTREE,
  INDEX `idx_ship_type_id`(`ship_type_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '船舶基础信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ship_info
-- ----------------------------

