  `cii_applicable` tinyint(1) NULL DEFAULT 0 COMMENT '是否适用CII（0:不适用 1:适用）',
  `cii_measure_standard` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CII计算度量标准（GT:总吨位 DWT:载重吨位）',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0:停用 1:启用）',
