-- ----------------------------
-- Table structure for ship_voyage
-- ----------------------------
DROP TABLE IF EXISTS `ship_voyage`;
CREATE TABLE `ship_voyage`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `start_port` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '起始港口',
  `start_port_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '起始港口代码（UN/LOCODE标准）',
  `end_port` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '终点港口',
  `end_port_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终点港口代码（UN/LOCODE标准）',
  `arrival_time` datetime NOT NULL COMMENT '到港时间',
  `departure_time` datetime NOT NULL COMMENT '离港时间',
  `arrival_purpose` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '到港目的',
  `route_distance` decimal(10, 2) NULL DEFAULT NULL COMMENT '航线距离（海里）',
  `fuel_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '燃料类型',
  `fuel_consumption` decimal(10, 2) NULL DEFAULT NULL COMMENT '燃料使用量（吨）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `total_eu_ets` decimal(15, 2) NULL DEFAULT NULL COMMENT 'Total EU ETS费用（欧元）',
  `auxiliary_fuel_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '辅助燃料类型',
  `auxiliary_fuel_consumption` decimal(10, 2) NULL DEFAULT NULL COMMENT '辅助燃料使用量',
  `shore_power_consumption` double NULL DEFAULT NULL COMMENT '岸电消耗（千瓦时）',
  `bdn_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '油料单路径',
  `charter_info_id` bigint(20) NULL DEFAULT NULL COMMENT '租期ID',
  `charterer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '承租人名称',
  `through_ice` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否通过冰区',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_ship_voyage_total_eu_ets`(`total_eu_ets`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  INDEX `idx_start_port_code`(`start_port_code`) USING BTREE,
  INDEX `idx_end_port_code`(`end_port_code`) USING BTREE,
  CONSTRAINT `fk_voyage_ship` FOREIGN KEY (`ship_id`) REFERENCES `ship_info` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 11196 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '船舶航次信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ship_voyage
-- ----------------------------

