-- Records of sys_user_role
-- ----------------------------

-- ----------------------------
-- Table structure for voyage_calculation_data
-- ----------------------------
DROP TABLE IF EXISTS `voyage_calculation_data`;
CREATE TABLE `voyage_calculation_data`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `voyage_id` bigint(20) NOT NULL COMMENT '航次ID',
  `ship_id` bigint(20) NOT NULL COMMENT '船舶ID',
  `charter_info_id` bigint(20) NULL DEFAULT NULL COMMENT '租期ID',
  `eu_port_coefficient` decimal(10, 2) NOT NULL COMMENT '欧盟港口系数 (0: 都不是欧盟, 0.5: 一个是欧盟, 1: 都是欧盟)',
  `wtt_numerator` decimal(20, 10) NULL DEFAULT NULL COMMENT 'Well to tank ship 分子',
  `wtt_denominator` decimal(20, 10) NULL DEFAULT NULL COMMENT 'Well to tank ship 分母',
  `ttw_numerator` decimal(20, 10) NULL DEFAULT NULL COMMENT 'Tank to wake ship 分子',
  `ttw_denominator` decimal(20, 10) NULL DEFAULT NULL COMMENT 'Tank to wake ship 分母',
  `calculation_status` tinyint(1) NULL DEFAULT 0 COMMENT '计算状态 (0: 未计算, 1: 已计算)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `energy_used_on_board` decimal(20, 10) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_voyage_id`(`voyage_id`) USING BTREE,
  INDEX `idx_ship_id`(`ship_id`) USING BTREE,
  INDEX `idx_charter_info_id`(`charter_info_id`) USING BTREE,
  INDEX `idx_calculation_status`(`calculation_status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1688 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '航次计算数据中间表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of voyage_calculation_data
-- ----------------------------

-- ----------------------------
-- Table structure for voyage_track_index
-- ----------------------------
DROP TABLE IF EXISTS `voyage_track_index`;
CREATE TABLE `voyage_track_index`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户ID',
  `voyage_id` bigint(20) NOT NULL COMMENT '航次ID',
  `mmsi` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '船舶MMSI号',
  `start_time` bigint(20) NOT NULL COMMENT '开始时间戳',
  `end_time` bigint(20) NOT NULL COMMENT '结束时间戳',
  `point_count` int(11) NOT NULL COMMENT '轨迹点数量',
  `file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件路径',
  `total_distance` double NULL DEFAULT NULL COMMENT '总航行距离（海里）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_voyage_id`(`voyage_id`) USING BTREE,
  INDEX `idx_mmsi_time`(`mmsi`, `start_time`, `end_time`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10286 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '航次轨迹索引表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of voyage_track_index
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
